//! Reproduce the ten behavior-boundary populations' generated LLVM IR.
//! Also generates the direct-call C driver and the independent zero-sign oracle.
//! Usage: zig run tools/generate_behavior_boundary_canaries.zig -- --output-root NEW
//! Optional --verify-root DIR compares every generated byte with checked-in fixtures.
const std = @import("std");
const u = @import("validation/common.zig");

pub fn main(init: std.process.Init) !void {
    var c = try u.Context.init(init);
    const argv = try init.minimal.args.toSlice(c.a);
    const args = try u.Args.parse(c.a, argv[1..], &.{ "output-root", "verify-root" }, &.{});
    const target = try c.newOutput(try args.require("output-root"));
    try booleanConstants(&c, target);
    try limbMultiply(&c, target);
    try limbSaturation(&c, target);
    try volatileNative(&c, target);
    try directCapacity(&c, target);
    try vectorStorage(&c, target);
    try literalCasts(&c, target);
    try floatingReductions(&c, target);
    try floatingMinmax(&c, target);
    try floatingZeroReference(&c, target);
    if (args.get("verify-root")) |root| for ([_][]const u8{
        "vector_bool_constants.ll", "limb_multiply.ll",               "limb_saturation.ll",
        "volatile_native.ll",       "direct_capacity.ll",             "direct_capacity_driver.c",
        "vector_storage.ll",        "integer_literal_casts.ll",       "floating_reductions.ll",
        "floating_minmax.ll",       "floating_minmax_mixed_zeros.ll", "floating_minmax_zero_reference.ll",
    }) |name| {
        if (!std.mem.eql(u8, try c.digest(try c.join(&.{ target, name })), try c.digest(try c.join(&.{ root, name })))) return error.GeneratedFixtureMismatch;
    };
    try c.print("behavior-boundary fixtures: 12 generated files{s}\n", .{if (args.get("verify-root") != null) ", byte-exact verification passed" else ""});
}
fn booleanConstants(c: *u.Context, target: []const u8) !void {
    var ir: std.Io.Writer.Allocating = .init(c.a);
    try ir.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    for ([_]usize{ 2, 3, 4, 7, 8, 16, 32, 64 }) |n| {
        try ir.writer.print("declare i1 @llvm.vector.reduce.or.v{d}i1(<{d} x i1>)\ndeclare i1 @llvm.vector.reduce.and.v{d}i1(<{d} x i1>)\n", .{ n, n, n, n });
        try ir.writer.print("define i64 @bool_constants_{d}(ptr %input, ptr %out, ptr %packed) {{\nentry:\n  %x = load <{d} x i1>, ptr %input, align 1\n  %flip = xor <{d} x i1> %x, splat (i1 true)\n  %even = select <{d} x i1> %x, <{d} x i1> <", .{ n, n, n, n, n });
        for (0..n) |i| {
            if (i != 0) try ir.writer.writeAll(", ");
            try ir.writer.print("i1 {s}", .{if (i % 2 == 0) "true" else "false"});
        }
        try ir.writer.print(">, <{d} x i1> splat (i1 false)\n  %expanded = zext <{d} x i1> %even to <{d} x i8>\n  store <{d} x i8> %expanded, ptr %out, align 1\n  store <{d} x i1> %flip, ptr %packed, align 1\n  %a = call i1 @llvm.vector.reduce.or.v{d}i1(<{d} x i1> %x)\n  %b = call i1 @llvm.vector.reduce.and.v{d}i1(<{d} x i1> %flip)\n  %a64 = zext i1 %a to i64\n  %b64 = zext i1 %b to i64\n  %bb = shl i64 %b64, 1\n  %r = or i64 %a64, %bb\n  ret i64 %r\n}}\n", .{ n, n, n, n, n, n, n, n, n });
    }
    try c.write(try c.join(&.{ target, "vector_bool_constants.ll" }), ir.written());
}

fn limbMultiply(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    for ([_]u16{ 140, 200, 256, 495 }) |bits| {
        const name = try c.fmt("limb_multiply_{d}", .{bits});
        for ([_][]const u8{ "umul", "smul" }) |op| try text.writer.print("declare {{i{0d},i1}} @llvm.{1s}.with.overflow.i{0d}(i{0d},i{0d})\n", .{ bits, op });
        try text.writer.print("define i64 @{s}(ptr %out,ptr %flags,ptr %xp,ptr %yp,i64 %salt) {{\nentry:\n %x = load i{d},ptr %xp,align 1\n %y = load i{d},ptr %yp,align 1\n", .{ name, bits, bits });
        for ([_][]const u8{ "umul", "smul" }, 0..) |op, i| {
            try text.writer.print(" %t{0d} = call {{i{1d},i1}} @llvm.{2s}.with.overflow.i{1d}(i{1d} %x,i{1d} %y)\n %v{0d} = extractvalue {{i{1d},i1}} %t{0d},0\n %f{0d} = extractvalue {{i{1d},i1}} %t{0d},1\n %b{0d} = zext i1 %f{0d} to i8\n %p{0d} = getelementptr i8,ptr %out,i64 {3d}\n store i{1d} %v{0d},ptr %p{0d},align 1\n %fp{0d} = getelementptr i8,ptr %flags,i64 {0d}\n store i8 %b{0d},ptr %fp{0d},align 1\n", .{ i, bits, op, i * 64 });
        }
        try text.writer.print(" %m = mul i{0d} %x,%y\n %mp = getelementptr i8,ptr %out,i64 128\n store i{0d} %m,ptr %mp,align 1\n %r = xor i64 %salt,90\n ret i64 %r\n}}\n", .{bits});
    }
    try c.write(try c.join(&.{ target, "limb_multiply.ll" }), text.written());
}

fn limbSaturation(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    const ops = [_][]const u8{ "umin", "umax", "smin", "smax", "umul.fix.sat", "smul.fix.sat", "ushl.sat", "sshl.sat" };
    for ([_]u16{ 140, 200, 256, 495 }) |bits| {
        const name = try c.fmt("limb_saturation_{d}", .{bits});
        for (ops, 0..) |op, i| try text.writer.print("declare i{0d} @llvm.{1s}.i{0d}(i{0d},i{0d}{2s})\n", .{ bits, op, if (i == 4 or i == 5) ",i32" else "" });
        try text.writer.print("define i64 @{s}(ptr %out,ptr %xp,ptr %yp,i64 %amount,i64 %salt) {{\nentry:\n %x = load i{d},ptr %xp,align 1\n %y = load i{d},ptr %yp,align 1\n %a = zext i64 %amount to i{d}\n", .{ name, bits, bits, bits });
        for (ops, 0..) |op, i| try text.writer.print(" %v{0d} = call i{1d} @llvm.{2s}.i{1d}(i{1d} %x,i{1d} %{3s}{4s})\n %p{0d} = getelementptr i8,ptr %out,i64 {5d}\n store i{1d} %v{0d},ptr %p{0d},align 1\n", .{ i, bits, op, if (i >= 6) "a" else "y", if (i == 4 or i == 5) ",i32 0" else "", i * 64 });
        try text.writer.writeAll(" %r = xor i64 %salt,90\n ret i64 %r\n}\n");
    }
    try c.write(try c.join(&.{ target, "limb_saturation.ll" }), text.written());
}

fn volatileNative(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    for ([_][]const u8{ "8", "16", "32", "64", "ptr" }) |width| {
        const pointer = std.mem.eql(u8, width, "ptr");
        const name = try c.fmt("volatile_native_{s}", .{width});
        const ty = if (pointer) "ptr" else try c.fmt("i{s}", .{width});
        try text.writer.print("define i64 @{s}(ptr %p,ptr %mid,ptr %final) {{\nentry:\n %a = load volatile {s},ptr %p,align 1\n store volatile {s} {s},ptr %p,align 1\n %unused = load volatile {s},ptr %p,align 1\n store volatile {s} undef,ptr %p,align 1\n %unspecified = load volatile {s},ptr %p,align 1\n store volatile {s} {s},ptr %p,align 1\n %c = load volatile {s},ptr %p,align 1\n", .{ name, ty, ty, if (pointer) "%mid" else "47", ty, ty, ty, ty, if (pointer) "%final" else "99", ty });
        const cast = if (pointer) "ptrtoint" else if (std.mem.eql(u8, width, "64")) "bitcast" else "zext";
        try text.writer.print(" %a64 = {s} {s} %a to i64\n %c64 = {s} {s} %c to i64\n %r = add i64 %a64,%c64\n ret i64 %r\n}}\n", .{ cast, ty, cast, ty });
    }
    try c.write(try c.join(&.{ target, "volatile_native.ll" }), text.written());
}

fn parameters(w: *std.Io.Writer, ty: []const u8, count: usize, llvm: bool) !void {
    for (0..count) |i| {
        if (i != 0) try w.writeAll(",");
        try w.print("{s} {s}a{d}", .{ ty, if (llvm) "%" else "", i });
    }
}
fn directCapacity(c: *u.Context, target: []const u8) !void {
    var ir: std.Io.Writer.Allocating = .init(c.a);
    var driver: std.Io.Writer.Allocating = .init(c.a);
    try ir.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    try driver.writer.writeAll("#define _GNU_SOURCE\n#include <stdint.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <sys/mman.h>\n#include <unistd.h>\n");
    for ([_]usize{ 32, 64 }) |bits| for ([_]usize{ 40, 64 }) |count| {
        const ty = try c.fmt("i{d}", .{bits});
        const cty = try c.fmt("uint{d}_t", .{bits});
        const name = try c.fmt("direct_capacity_{d}_{d}", .{ bits, count });
        const caller = try c.fmt("direct_capacity_call_{d}_{d}", .{ bits, count });
        const external = try c.fmt("direct_capacity_external_{d}_{d}", .{ bits, count });
        try driver.writer.print("extern uint64_t {s}(", .{name});
        try parameters(&driver.writer, cty, count, false);
        try driver.writer.print(");\nextern uint64_t {s}(const void *,uint64_t,uint64_t *);\nuint64_t {s}(", .{ caller, external });
        try parameters(&driver.writer, cty, count, false);
        try driver.writer.writeAll(") {uint64_t h=(uint64_t)a0^90;\n");
        for (1..count) |i| try driver.writer.print("h=((h<<7)|(h>>57))^(uint64_t)a{d};\n", .{i});
        try driver.writer.writeAll("return h;}\n");
        try ir.writer.print("define i64 @{s}(", .{name});
        try parameters(&ir.writer, ty, count, true);
        try ir.writer.writeAll(") {\nentry:\n");
        for (0..count) |i| {
            const value = try c.fmt("%{s}{d}", .{ if (bits == 32) "v" else "a", i });
            if (bits == 32) try ir.writer.print(" %v{d} = zext i32 %a{d} to i64\n", .{ i, i });
            if (i == 0) {
                try ir.writer.print(" %h0 = xor i64 {s},90\n", .{value});
            } else try ir.writer.print(" %l{0d} = shl i64 %h{1d},7\n %r{0d} = lshr i64 %h{1d},57\n %rot{0d} = or i64 %l{0d},%r{0d}\n %h{0d} = xor i64 %rot{0d},{2s}\n", .{ i, i - 1, value });
        }
        try ir.writer.print(" ret i64 %h{d}\n}}\ndeclare i64 @{s}(", .{ count - 1, external });
        for (0..count) |i| {
            if (i != 0) try ir.writer.writeAll(",");
            try ir.writer.writeAll(ty);
        }
        try ir.writer.print(")\ndefine i64 @{s}(ptr %input,i64 %salt,ptr %out) {{\nentry:\n", .{caller});
        for (0..count) |i| if (i % 3 != 0) try ir.writer.print(" %p{0d} = getelementptr i8,ptr %input,i64 {1d}\n %v{0d} = load {2s},ptr %p{0d},align 1\n", .{ i, (count - 1 - i) * (bits / 8), ty });
        try ir.writer.print(" %value = call i64 @{s}(", .{external});
        for (0..count) |i| {
            if (i != 0) try ir.writer.writeAll(",");
            if (i % 3 == 0) try ir.writer.print("{s} {d}", .{ ty, 100 + i }) else try ir.writer.print("{s} %v{d}", .{ ty, i });
        }
        try ir.writer.writeAll(")\n store i64 %value,ptr %out,align 1\n %next = getelementptr i8,ptr %out,i64 8\n store i64 %salt,ptr %next,align 1\n %r = xor i64 %value,%salt\n ret i64 %r\n}\n");
    };
    try driver.writer.writeAll("static uint64_t fold(const uint64_t *p,unsigned n){uint64_t h=p[0]^90;for(unsigned i=1;i<n;i++)h=((h<<7)|(h>>57))^p[i];return h;}\nint main(int argc,char **argv){unsigned fault=argc>1?(unsigned)strtoul(argv[1],NULL,10):0;size_t observations=0;size_t page=(size_t)sysconf(_SC_PAGESIZE);uint8_t *map=mmap(NULL,page*3,PROT_NONE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);if(map==MAP_FAILED||mprotect(map+page,page,PROT_READ|PROT_WRITE))return 2;\n#define CHECK(c) do{++observations;if(!(c)){fprintf(stderr,\"direct-capacity bits=%u count=%u seed=%u observation=%zu fault=%u\\n\",bits,count,seed,observations,fault);return 1;}}while(0)\n");
    for ([_]usize{ 32, 64 }) |bits| for ([_]usize{ 40, 64 }) |count| {
        try driver.writer.print("{{const unsigned bits={d},count={d};for(unsigned seed=0;seed<64;seed++){{uint64_t values[64],transformed[64];uint8_t saved[512];unsigned bytes=count*(bits/8);uint8_t *input=map+2*page-bytes;for(unsigned i=0;i<count;i++){{uint64_t v=(UINT64_C(0xf06dea67e461de5b)*(seed+1))^(UINT64_C(0x9e3779b97f4a7c15)*(i+3));if(bits==32)v=(uint32_t)v;values[i]=v;memcpy(input+i*(bits/8),&v,bits/8);}}memcpy(saved,input,bytes);for(unsigned i=0;i<count;i++)transformed[i]=i%3==0?100+i:values[count-1-i];uint64_t incoming=direct_capacity_{d}_{d}(", .{ bits, count, bits, count });
        for (0..count) |i| {
            if (i != 0) try driver.writer.writeAll(",");
            try driver.writer.print("(uint{d}_t)values[{d}]", .{ bits, i });
        }
        try driver.writer.print(");struct{{uint64_t pre,data[2],post;}}out;memset(&out,0xa5,sizeof out);uint64_t salt=UINT64_C(0x8123456789abcdef)^seed;uint64_t returned=direct_capacity_call_{d}_{d}(input,salt,out.data);if(fault==1)incoming^=1;if(fault==2)out.data[0]^=1;if(fault==3)out.post^=1;uint64_t wanted=fold(transformed,count);CHECK(incoming==fold(values,count));CHECK(returned==(wanted^salt));CHECK(out.data[0]==wanted);CHECK(out.data[1]==salt);CHECK(out.pre==UINT64_C(0xa5a5a5a5a5a5a5a5));CHECK(out.post==UINT64_C(0xa5a5a5a5a5a5a5a5));CHECK(memcmp(input,saved,bytes)==0);}}}}\n", .{ bits, count });
    };
    try driver.writer.writeAll("printf(\"direct-capacity observations=%zu incoming-outgoing=40-and-64=constants=permutations=live-values=guards=preserved\\n\",observations);return munmap(map,page*3)!=0;}\n");
    try c.write(try c.join(&.{ target, "direct_capacity.ll" }), ir.written());
    try c.write(try c.join(&.{ target, "direct_capacity_driver.c" }), driver.written());
}

fn vectorStorage(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\ndeclare i64 @vector_storage_touch(ptr,ptr,ptr,ptr,ptr,i64,i64)\n");
    for ([_][2]u32{ .{ 16, 32 }, .{ 17, 32 }, .{ 3, 64 }, .{ 64, 64 } }) |shape| {
        const n = shape[0];
        const bits = shape[1];
        const bytes = n * bits / 8;
        const alignment = try std.math.ceilPowerOfTwo(u32, bytes);
        const ty = try c.fmt("<{d} x i{d}>", .{ n, bits });
        const name = try c.fmt("vector_storage_{d}_{d}", .{ n, bits });
        try text.writer.print("define i64 @{s}(ptr %out,ptr %xp,ptr %yp,i64 %salt) {{\nentry:\n %av = alloca {s},align {d}\n %bv = alloca {s},align {d}\n %array = alloca [3 x {s}],align {d}\n", .{ name, ty, alignment, ty, alignment, ty, alignment });
        for (0..3) |i| try text.writer.print(" %ar{d} = getelementptr [3 x {s}],ptr %array,i64 0,i64 {d}\n", .{ i, ty, i });
        try text.writer.print(" %x = load {s},ptr %xp,align 1\n %y = load {s},ptr %yp,align 1\n", .{ ty, ty });
        for ([_][]const u8{ "add", "sub", "xor" }, 0..) |op, i| try text.writer.print(" %v{d} = {s} {s} %x,%y\n store {s} %v{d},ptr %ar{d},align {d}\n", .{ i, op, ty, ty, i, i, alignment });
        try text.writer.print(" store {s} %x,ptr %av,align {d}\n store {s} %y,ptr %bv,align {d}\n %h = call i64 @vector_storage_touch(ptr %av,ptr %bv,ptr %ar0,ptr %ar1,ptr %ar2,i64 {d},i64 {d})\n", .{ ty, alignment, ty, alignment, bytes, alignment });
        for ([_][]const u8{ "av", "bv", "ar0", "ar1", "ar2" }, 0..) |ptr, i| try text.writer.print(" %o{d} = getelementptr i8,ptr %out,i64 {d}\n %r{d} = load {s},ptr %{s},align {d}\n store {s} %r{d},ptr %o{d},align 1\n", .{ i, i * 512, i, ty, ptr, alignment, ty, i, i });
        try text.writer.writeAll(" %answer = xor i64 %h,%salt\n ret i64 %answer\n}\n");
    }
    try c.write(try c.join(&.{ target, "vector_storage.ll" }), text.written());
}

fn literalCasts(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\ndefine i64 @integer_literal_casts(ptr %out,i64 %salt,i64 %seed) {\nentry:\n");
    var index: usize = 0;
    for ([_]u16{ 2, 3, 6, 7, 9, 15, 17, 31, 33, 47, 52, 62, 63 }) |bits| {
        const sign = @as(i128, 1) << @as(u7, @intCast(bits - 1));
        const limit = @as(i128, 1) << @as(u7, @intCast(bits));
        for ([_]u16{ 8, 16, 32, 64 }) |dest| if (dest > bits) {
            for ([_]i128{ 0, 1, -1, -sign, sign - 1, limit - 1 }) |literal| {
                try text.writer.print(" %s{d} = zext i{d} {d} to i{d}\n", .{ index, bits, literal, dest });
                if (dest != 64) try text.writer.print(" %w{d} = zext i{d} %s{d} to i64\n", .{ index, dest, index }) else try text.writer.print(" %w{d} = xor i64 %s{d},0\n", .{ index, index });
                try text.writer.print(" %m{0d} = xor i64 %w{0d},%salt\n %v{0d} = add i64 %m{0d},%seed\n %p{0d} = getelementptr i8,ptr %out,i64 {1d}\n store i64 %v{0d},ptr %p{0d},align 1\n", .{ index, index * 8 });
                index += 1;
            }
        };
    }
    if (index != 186) return error.IncorrectCaseCount;
    try text.writer.writeAll(" %r = xor i64 %seed,%salt\n ret i64 %r\n}\n");
    try c.write(try c.join(&.{ target, "integer_literal_casts.ll" }), text.written());
}

fn floatingReductions(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    for ([_][]const u8{ "half", "float", "double", "x86_fp80", "fp128" }, [_]u16{ 16, 32, 64, 80, 128 }) |ty, bits| {
        for ([_]u32{ 2, 3, 4 }) |count| for ([_][]const u8{ "add", "mul" }) |op| {
            const name = try c.fmt("floating_reduce_{d}_{d}_{s}", .{ bits, count, op });
            try text.writer.print("declare {0s} @llvm.vector.reduce.f{1s}.v{2d}f{3d}({0s},<{2d} x {0s}>)\ndefine i64 @{4s}(ptr %out,ptr %in,ptr %seed,i64 %salt) {{\nentry:\n %v = load <{2d} x {0s}>,ptr %in,align 1\n %s = load {0s},ptr %seed,align 1\n %r = call {0s} @llvm.vector.reduce.f{1s}.v{2d}f{3d}({0s} %s,<{2d} x {0s}> %v)\n store {0s} %r,ptr %out,align 1\n %live = xor i64 %salt,90\n ret i64 %live\n}}\n", .{ ty, op, count, bits, name });
        };
    }
    try c.write(try c.join(&.{ target, "floating_reductions.ll" }), text.written());
}

fn floatingMinmax(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    for ([_][]const u8{ "half", "float", "double", "x86_fp80", "fp128" }, [_]u16{ 16, 32, 64, 80, 128 }) |ty, bits| {
        try text.writer.print("declare {0s} @llvm.maxnum.f{1d}({0s},{0s})\n", .{ ty, bits });
        for ([_]u32{ 2, 3, 4 }) |count| for ([_][]const u8{ "min", "max" }) |op| {
            const name = try c.fmt("floating_minmax_{d}_{d}_{s}", .{ bits, count, op });
            try text.writer.print("declare {0s} @llvm.vector.reduce.f{1s}.v{2d}f{3d}(<{2d} x {0s}>)\ndefine i64 @{4s}(ptr %out,ptr %in,i64 %salt) {{\nentry:\n %v = load <{2d} x {0s}>,ptr %in,align 1\n %r = call {0s} @llvm.vector.reduce.f{1s}.v{2d}f{3d}(<{2d} x {0s}> %v)\n store {0s} %r,ptr %out,align 1\n %live = xor i64 %salt,90\n ret i64 %live\n}}\n", .{ ty, op, count, bits, name });
        };
    }
    try c.write(try c.join(&.{ target, "floating_minmax.ll" }), text.written());

    try c.write(try c.join(&.{ target, "floating_minmax_mixed_zeros.ll" }), text.written());
}

fn floatingZeroReference(c: *u.Context, target: []const u8) !void {
    var text: std.Io.Writer.Allocating = .init(c.a);
    try text.writer.writeAll("; Independent zero-sign oracle: pinned vector reduction supplies numeric/NaN results.\n; Vector sign and zero masks repair its demonstrated zero-tie limitation.\n; Candidate IR is retained unchanged in floating_minmax_mixed_zeros.ll.\n");
    try text.writer.writeAll("target datalayout = \"e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-i128:128-f80:128-n8:16:32:64-S128\"\ntarget triple = \"x86_64-unknown-linux-gnu\"\n");
    for ([_]u32{ 2, 3, 4 }) |count| {
        for ([_][]const u8{ "or", "and" }) |op| try text.writer.print("declare i1 @llvm.vector.reduce.{s}.v{d}i1(<{d} x i1>)\n", .{ op, count, count });
    }
    for ([_][]const u8{ "half", "float", "double", "x86_fp80", "fp128" }, [_]u16{ 16, 32, 64, 80, 128 }) |ty, bits| {
        const positive = if (bits == 16) "0xH0000" else if (bits == 80) "0xK00000000000000000000" else if (bits == 128) "0xL00000000000000000000000000000000" else "0.000000e+00";
        const negative = if (bits == 16) "0xH8000" else if (bits == 80) "0xK80000000000000000000" else if (bits == 128) "0xL00000000000000008000000000000000" else "-0.000000e+00";
        for ([_]u32{ 2, 3, 4 }) |count| for ([_][]const u8{ "min", "max" }) |op| {
            const minimum = std.mem.eql(u8, op, "min");
            const name = try c.fmt("floating_minmax_{d}_{d}_{s}", .{ bits, count, op });
            try text.writer.print("declare {0s} @llvm.vector.reduce.f{1s}.v{2d}f{3d}(<{2d} x {0s}>)\ndefine i64 @{4s}(ptr %out,ptr %in,i64 %salt) {{\nentry:\n %v = load <{2d} x {0s}>,ptr %in,align 1\n %ordinary = call {0s} @llvm.vector.reduce.f{1s}.v{2d}f{3d}(<{2d} x {0s}> %v)\n %zeros = fcmp oeq <{2d} x {0s}> %v,zeroinitializer\n %raw = bitcast <{2d} x {0s}> %v to <{2d} x i{3d}>\n %negative = icmp slt <{2d} x i{3d}> %raw,zeroinitializer\n", .{ ty, op, count, bits, name });
            if (minimum) {
                try text.writer.print(" %mask = and <{d} x i1> %zeros,%negative\n", .{count});
            } else {
                try text.writer.print(" %mask = select <{d} x i1> %zeros,<{d} x i1> %negative,<{d} x i1> <", .{ count, count, count });
                for (0..count) |index| {
                    if (index != 0) try text.writer.writeAll(",");
                    try text.writer.writeAll("i1 true");
                }
                try text.writer.writeAll(">\n");
            }
            try text.writer.print(" %sign = call i1 @llvm.vector.reduce.{s}.v{d}i1(<{d} x i1> %mask)\n %correct_zero = select i1 %sign,{s} {s},{s} {s}\n %is_zero = fcmp oeq {s} %ordinary,{s}\n %answer = select i1 %is_zero,{s} %correct_zero,{s} %ordinary\n store {s} %answer,ptr %out,align 1\n %live = xor i64 %salt,90\n ret i64 %live\n}}\n", .{ if (minimum) "or" else "and", count, count, ty, negative, ty, positive, ty, positive, ty, ty, ty });
        };
    }
    const reference = try c.join(&.{ target, "floating_minmax_zero_reference.ll" });
    try c.write(reference, text.written());
}
